  "enunciado": "A prefeitura de um município, dependendo do consumo mensal C de água, em litro, concederá ao consumidor um dos cinco tipos de desconto:\n- tipo 1, se 29000 é menor ou igual a C que é menor ou igual a 30000;\n- tipo 2, se 27500 é menor ou igual a C que é menor que 29000;\n- tipo 3, se 26000 é menor ou igual a C que é menor que 27500;\n- tipo 4, se 24000 é menor ou igual a C que é menor que 26000;\n- tipo 5, se C é menor que 24000.\n\nO desconto será aplicado no valor da conta a ser paga, e não será concedido desconto para contas com consumo superior a 30000 litros.\nUm consumidor, no primeiro mês, não obteve desconto. Se consumisse 40 por cento a menos de água, alcançaria o consumo máximo estabelecido para conseguir o desconto do tipo 1. No segundo mês, seu consumo de água reduziu 20 por cento em relação ao consumo do primeiro mês; e no terceiro mês, seu consumo de água reduziu 30 por cento em relação ao consumo do segundo mês.\n\nAssim, no terceiro mês, esse consumidor receberá desconto do tipo",
