  "enunciado": "Em uma loja, um computador é vendido por 2000 reais à vista ou, de forma financiada, mediante uma entrada e mais 15 parcelas mensais iguais, envolvendo cobrança de juros. Inicialmente, um cliente propôs dar 500 reais de entrada e, para esse caso, o vendedor calculou em 150 reais o valor das prestações mensais. Para facilitar a escolha do cliente, o vendedor informou que cada 1 real de redução no valor das prestações corresponde a um acréscimo de 10 reais no valor da entrada. Com essas informações, o cliente decidiu pela compra financiada, pagando prestações mensais de 120 reais.\n\nQuanto, em real, esse cliente deve acrescentar ao valor inicial de sua proposta de entrada para viabilizar as prestações no valor de 120 reais?",
