  "prova": {
   "banca": "INEP",
   "ano": 2024,
   "orgao": "ENEM, reaplicação/PPL, 1º dia, questão 24"
  },
  "enunciado": "Perto do coração selvagem Clarice Lispector Sim, ela sentia dentro de si um animal perfeito. Repugnava-lhe deixar um dia esse animal solto. Por medo talvez da falta de estética. Ou receio de alguma revelação... Não, não, — repetia-se ela — é preciso não ter medo de criar. No fundo de tudo possivelmente o animal repugnava-lhe porque ainda havia nela o desejo de agradar e de ser amada por alguém poderoso como a tia morta. Para depois no entanto pisá-la, repudiá-la sem contemplações. Porque a melhor frase, sempre ainda a mais jovem, era: a bondade me dá ânsias de vomitar. A bondade era morna e leve, cheirava a carne crua guardada há muito tempo. Sem apodrecer inteiramente apesar de tudo. Refrescavam-na de quando em quando, botavam um pouco de tempero, o suficiente para conservá-la um pedaço de carne morna e quieta.\n\nNessa passagem, a reflexão feita pela personagem resulta da sua tomada de consciência da",
  "alternativas": [
   "inclinação do ser humano para o egoísmo.",
   "violência sofrida pelos membros da família.",
   "dissimulação praticada em nome da convivência.",
   "dificuldade de relacionamento entre as gerações.",
   "postura de desdém pela memória da tia morta."
  ],
  "resposta": 2,
