  "enunciado": "Um tanque de armazenamento de líquidos tem o formato de uma pirâmide reta de base quadrada, cujo plano que contém essa base é paralelo a um solo plano e horizontal. Esse tanque tem capacidade de 240 litros e altura de 2 metros. Inicialmente vazio, nele é despejado um líquido à vazão constante de 0,015 metro cúbico por segundo. Sabe-se que 1 litro igual a 1 decímetro cúbico igual a 0,001 metro cúbico.\n\nDescrição da figura: Figura representa uma pirâmide reta, de base quadrada, com o vértice apontando para baixo.\n\nQual expressão fornece a altura, em metro, da coluna de líquido dentro desse tanque em função do tempo t, em segundo?",
