  "enunciado": "Num dia de promoção, um supermercado propõe dar desconto em um produto e, mantendo fixo o preço da unidade, apresenta ao consumidor as seguintes propostas:\n\n• opção 1: pague 8 e leve 9 unidades;\n• opção 2: leve 8 e pague 7 unidades. Um consumidor quer escolher a opção que lhe oferecerá o maior desconto percentual.\n\nA opção que oferece o maior desconto, e o percentual desse desconto é",
