  "enunciado": "Para reforçar sua renda familiar, uma pessoa inaugurou um estabelecimento que vende refrigerantes. Ela adquiriu um tipo de refrigerante para revenda no primeiro mês de funcionamento do estabelecimento. Foram compradas 20 caixas desse refrigerante, pagando 18 reais a caixa, com 12 latas cada. Ao final desse mês, obteve 600 reais de lucro com a venda de todas as latas. No segundo mês, ela compra a mesma quantidade de latas de refrigerante comprada no primeiro mês, pelo mesmo preço, e decide aumentar o preço de venda de cada lata de refrigerante, de modo a aumentar o seu lucro em 360 reais em relação ao lucro do mês anterior.\n\nQual será o novo preço de venda, em real, de cada lata de refrigerante?",
