  "enunciado": "Uma escala termométrica X marca menos 10 graus X para o ponto de fusão da água e 140 graus X para o seu ponto de ebulição. Na escala Celsius, as temperaturas de fusão e de ebulição da água são 0 grau Celsius e 100 graus Celsius, respectivamente. O gráfico que expressa a relação entre essas duas escalas é uma reta. A figura apresenta a representação de cinco gráficos (1, 2, 3, 4 e 5) num sistema de coordenadas cartesianas.\n\nDescrição da figura: Gráfico de cinco retas, representadas num mesmo sistema de coordenadas cartesianas, de eixo horizontal referente à temperatura em grau Celsius e eixo vertical referente à temperatura em grau X: reta 1: passa pelos pontos (menos 10 ; 0) e (140 ; 100); reta 2: passa pelos pontos (0 ; menos 10) e (100 ; 140); reta 3: passa pelos pontos (menos 10 ; 140) e (0 ; 100); reta 4: passa pelos pontos (100 ; 140) e (140 ; 100); reta 5: passa pelos pontos (menos 10 ; menos 10) e (140 ; 140).\n\nQual gráfico representa a relação entre as temperaturas nas escalas Celsius e X?",
