  "enunciado": "Uma piscina de um clube tem o formato de paralelepípedo reto retângulo com 50 metros de comprimento, 25 metros de largura e 3 metros de profundidade. O proprietário do clube construirá duas novas piscinas, de formatos diferentes, e necessita que cada uma tenha o mesmo volume da existente ou o mais próximo possível desse volume. A empresa de construção contratada disponibilizou, para a avaliação desse proprietário, uma proposta com cinco projetos de piscina: três com o formato de cilindro circular reto e duas com o formato de paralelepípedo reto retângulo:\n• piscina cilíndrica 1 (C índice 1): 50 metros de diâmetro de base e 2 metros de profundidade;\n• piscina cilíndrica 2 (C índice 2): 40 metros de diâmetro de base e 3 metros de profundidade;\n• piscina cilíndrica 3 (C índice 3): 46 metros de diâmetro de base e 2,5 metros de profundidade;\n• piscina em formato de paralelepípedo 1 (P índice 1): 62 metros de comprimento, 24 metros de largura e 2 metros de profundidade;\n• piscina em formato de paralelepípedo 2 (P índice 2): 64 metros de comprimento, 30 metros de largura e 2 metros de profundidade. Considere 3 como valor aproximado de pi. Para atender às suas necessidades, dentre os projetos propostos, o proprietário desse clube deverá escolher as piscinas",
