  "enunciado": "Especialistas do Instituto Internacional de Águas de Estocolmo estimam que cada pessoa necessita de, no mínimo, 1 000 metros cúbicos de água por ano, para consumo, higiene e cultivo de alimentos. Sabe-se também que o Rio Amazonas despeja 200 000 metros cúbicos de água no mar por segundo. Por quanto tempo deveríamos coletar as águas que o Rio Amazonas despeja no mar para manter a população da cidade de São Paulo, estimada em 20 milhões de pessoas, por um ano?",
