  "enunciado": "Os países anglófonos, como a Inglaterra, o Canadá, a Austrália e outros, são países que utilizam dois sistemas de unidades para a identificação de distâncias: o Sistema Internacional, com o quilômetro cujo símbolo é km, e o CGS, com a milha cujo símbolo é mi. Nas rodovias canadenses, por exemplo, as placas de sinalização de distâncias apresentam dois valores, um em quilômetro e outro em milha, com esta última equivalente a aproximadamente 1 610 metros. Um turista brasileiro, habituado ao Sistema Internacional, em viagem por uma dessas rodovias, verifica em dado momento uma placa indicando a distância até a cidade a que ele se destina, onde está escrito 50 milhas e XX quilômetros, com o valor da distância em quilômetro ilegível. Qual o valor, desprezando as casas decimais, que deveria estar escrito na placa, para identificar a distância XX, em quilômetro, até a cidade destino?",
