  "enunciado": "Um cliente vai a uma loja de materiais de revestimento cerâmico para adquirir porcelanato para a substituição do piso de uma sala com formato retangular, com área total de 36 metros quadrados. O vendedor dessa loja lhe oferece dois projetos.\n• Projeto A: porcelanato quadrado, com 0,60 metro de lado, para ser disposto de maneira que a diagonal do quadrado seja paralela ao contorno da sala. Custo da caixa com 10 peças: 60 reais.\n• Projeto B: porcelanato quadrado, com 0,40 metro de lado, para ser disposto de maneira que os lados do quadrado sejam paralelos ao contorno da sala. Custo da caixa com 12 peças: 40 reais. O vendedor informa que a fábrica recomenda a compra de uma quantidade adicional do número de peças para eventual necessidade de cortes e para reserva. No caso do projeto A, devem ser adquiridos 25 por cento a mais, e no caso do projeto B, uma quantidade 10 por cento maior do que o valor exato da área de recobrimento. O cliente decide, então, que irá adotar o projeto de menor custo. O custo mínimo que o cliente deverá ter, em conformidade com seu objetivo e com as informações apresentadas, será de",
