  "enunciado": "Um casal tentou ter filhos naturalmente por muito tempo. Sem sucesso, resolveram procurar uma clínica de reprodução e fazer uso de técnicas de fertilização in vitro. Em um primeiro procedimento, conseguiram produzir um único embrião. O médico sugeriu o congelamento desse embrião e a repetição do processo, que originou um segundo embrião. Esses dois embriões foram então implantados no útero em um único procedimento e, para felicidade do casal, seguiu-se uma gestação gemelar com sucesso.\n\nNessa situação, os gêmeos são",
