  "enunciado": "Um agricultor, interessado em iniciar um cultivo orgânico, decidiu avaliar o efeito da ação das lagartas sobre plantas jovens de feijão. O experimento consistiu em plantio de sementes de feijão em canteiro com solo fértil e úmido. As sementes germinaram após alguns dias e originaram plantas saudáveis. Quando essas plantas estavam com quatro pares de folhas definitivas, o agricultor adicionou lagartas que predaram apenas a gema apical dessas plantas.\n\nApós sete dias, as plantas estavam",
