  "enunciado": "Atualmente, muito se discute a respeito da necessidade crescente de produção de energia elétrica. As usinas hidrelétricas são consideradas fontes de energia limpa, sustentável e renovável. Entretanto, toda intervenção humana no ambiente gera impactos. O alagamento de grandes áreas devido à construção de usinas, entre outras consequências, pode interferir no equilíbrio da flora e da fauna locais. No caso de espécies endêmicas, o impacto pode ser ainda maior, levando até mesmo à sua extinção.\n\nNesse contexto, para o manejo após o impacto, é importante que estudos prévios sejam feitos com o objetivo de",
  "alternativas": [
   "avaliar a potabilidade da água.",
   "monitorar a biodiversidade local.",
   "estimular a introdução de espécies exóticas.",
   "promover a variedade de espécies lacustres.",
   "favorecer a emigração das espécies silvestres."
  ],
