  "enunciado": "Uma empresa foi fundada por 3 sócios, que combinaram que iriam distribuir o lucro obtido ao final de 18 meses. Essa distribuição será feita em partes diretamente proporcionais ao investimento feito por sócio e ao tempo em que cada um deles permanecer como sócio. Passados 6 meses da criação dessa empresa, o sócio que havia investido 5000 reais saiu da sociedade. Os outros dois sócios, um que investiu 4000 reais e o outro que investiu 6000 reais, permaneceram os 18 meses. Ao final desse período, o lucro total de 21000 reais foi distribuído.\n\nA parte do lucro, em real, destinada ao sócio que saiu da sociedade foi",
