  "enunciado": "A diretora de uma creche coletou, das cadernetas de vacinação de cinco crianças, a informação sobre o número de doses de vacinas aplicadas nos primeiros quatro semestres de vida. A seguir são apresentadas as sequências das quantidades de doses que cada criança recebeu no primeiro, segundo, terceiro e quarto semestres, respectivamente:\n- criança 1: 10, 5, 5, 5;\n- criança 2: 12, 3, 5, 5;\n- criança 3: 13, 4, 5, 4;\n- criança 4: 11, 5, 5, 3;\n- criança 5: 13, 3, 7, 3.\n\nA diretora fará uma reunião com os pais das crianças dessa creche com o objetivo de conscientizá-los da importância de completarem as doses de vacinas que faltam. Para ilustrar a importância desse assunto, ela escolherá os dados de uma dessas cinco cadernetas para apresentar na reunião. Serão escolhidos os dados da caderneta de vacinação que apresentar a menor média semestral das quantidades de doses de vacinas aplicadas nos primeiros quatro semestres de vida dessas crianças.\n\nA caderneta que contém os dados a serem escolhidos pela diretora para a reunião é a da criança",
