  "enunciado": "No Brasil, datas são registradas no formato D D/M M, em que os primeiros dois dígitos codificam o dia do mês, e os dois seguintes, o mês do ano. Em alguns países, esses registros se dão no formato M M/D D, no qual se indica primeiro o mês do ano e depois o dia do mês. Por exemplo, a data 9 de maio é registrada, no Brasil, no formato 09/05, enquanto em alguns países, essa mesma data é registrada no formato 05/09.\nUm aplicativo gerará aleatoriamente uma data (dia e mês) de um ano não bissexto.\n\nQual é a probabilidade de que a data gerada tenha o mesmo registro nos dois formatos considerados?",
