  "enunciado": "Um casal planeja construir em sua chácara uma piscina com o formato de um paralelepípedo reto retângulo com capacidade para 90 000 litros de água. O casal contratou uma empresa de construções que apresentou cinco projetos com diferentes combinações nas dimensões internas de profundidade, largura e comprimento. A piscina a ser construída terá revestimento interno em suas paredes e fundo com uma mesma cerâmica, e o casal irá escolher o projeto que exija a menor área de revestimento. As dimensões internas de profundidade, largura e comprimento, respectivamente, para cada um dos projetos, são:\n• projeto 1: 1,8 metro, 2,0 metros e 25,0 metros;\n• projeto 2: 2,0 metros, 5,0 metros e 9,0 metros;\n• projeto 3: 1,0 metro, 6,0 metros e 15,0 metros;\n• projeto 4: 1,5 metro, 15,0 metros e 4,0 metros;\n• projeto 5: 2,5 metros, 3,0 metros e 12,0 metros. O projeto que o casal deverá escolher será o",
