  "enunciado": "A World Series é a decisão do campeonato norte-americano de beisebol. Os dois times que chegam a essa fase jogam, entre si, até sete partidas. O primeiro desses times que completar quatro vitórias é declarado campeão. Considere que, em todas as partidas, a probabilidade de qualquer um dos dois times vencer é sempre fração com numerador 1 e denominador 2. Qual é a probabilidade de o time campeão ser aquele que venceu a primeira partida da World Series?",
