  "enunciado": "O técnico de um time de basquete pretende aumentar a estatura média de sua equipe de 1,93 metros para, no mínimo, 1,99 metros. Para tanto, dentre os 15 jogadores que fazem parte de sua equipe, irá substituir os quatro mais baixos, de estaturas: 1,78 metros, 1,82 metros, 1,84 metros e 1,86 metros. Para isso, o técnico contratou um novo jogador de 2,02 metros. Os outros três jogadores que ele ainda precisa contratar devem satisfazer à sua necessidade de aumentar a média das estaturas da equipe. Ele fixará a média das estaturas para os três jogadores que ainda precisa contratar dentro do critério inicialmente estabelecido. Qual deverá ser a média mínima das estaturas, em metro, que ele deverá fixar para o grupo de três novos jogadores que ainda irá contratar?",
