  "enunciado": "Num recipiente com a forma de paralelepípedo reto-retângulo, colocou-se água até a altura de 8 centímetros e um objeto, que ficou flutuando na superfície da água. Para retirar o objeto de dentro do recipiente, a altura da coluna de água deve ser de, pelo menos, 15 centímetros. Para a coluna de água chegar até essa altura, é necessário colocar dentro do recipiente bolinhas de volume igual a 6 centímetros cúbicos cada, que ficarão totalmente submersas.\n\nDescrição da imagem: O recipiente com indicação de água à altura de 8 centímetros tem altura de 17 centímetros; 4 centímetros de comprimento e 3 centímetros de largura.\n\nO número mínimo de bolinhas necessárias para que se possa retirar o objeto que flutua na água, seguindo as instruções dadas, é de",
