  "enunciado": "O Estatuto do Idoso, no Brasil, prevê certos direitos às pessoas com idade avançada, concedendo a estas, entre outros benefícios, a restituição de imposto de renda antes dos demais contribuintes. A tabela informa os nomes e as idades de 12 idosos que aguardam suas restituições de imposto de renda. Considere que, entre os idosos, a restituição seja concedida em ordem decrescente de idade e que, em subgrupos de pessoas com a mesma idade, a ordem seja decidida por sorteio.\n\nDescrição da tabela: A tabela apresenta os nomes dos idosos e as respectivas idades, em ano.\n\nOrlando: 89 anos; Gustavo: 86 anos; Luana: 86 anos; Teresa: 85 anos; Márcia: 84 anos; Roberto: 82 anos; Heloísa: 75 anos; Marisa: 75 anos; Pedro: 75 anos; João: 75 anos; Antônio: 72 anos; Fernanda: 70 anos.\n\nNessas condições, a probabilidade de João ser a sétima pessoa do grupo a receber sua restituição é igual a",
