  "enunciado": "Uma cozinheira colocou sal a mais no feijão que estava cozinhando. Para solucionar o problema, ela acrescentou batatas cruas e sem tempero dentro da panela. Quando terminou de cozinhá-lo, as batatas estavam salgadas, porque absorveram parte do caldo com excesso de sal. Finalmente, ela adicionou água para completar o caldo do feijão. O sal foi absorvido pelas batatas por",
  "alternativas": [
   "osmose, por envolver apenas o transporte do solvente.",
   "fagocitose, porque o sal transportado é uma substância sólida.",
   "exocitose, uma vez que o sal foi transportado da água para a batata.",
   "pinocitose, porque o sal estava diluído na água quando foi transportado.",
   "difusão, porque o transporte ocorreu a favor do gradiente de concentração."
  ],
