  "enunciado": "Uma das técnicas de reciclagem química do polímero PET [poli(tereftalato de etileno)] gera o tereftalato de metila e o etanodiol, conforme o esquema de reação, e ocorre por meio de uma reação de transesterificação.\n\nDescrição do esquema de reação:\n\nO polímero PET reage com 2 n do composto A, sob condições de altas temperaturas e pressão, formando dois produtos. O reagente PET é um polímero de n monômeros com a estrutura, entre colchetes, de um anel aromático com grupo CO ligado ao carbono 1 e COO ligado ao carbono 4. O oxigênio do grupo COO do carbono 4 faz ligação simples com o grupo CH2CH2O. Um dos produtos formado tem n moléculas de um composto que contém um anel aromático com grupos COOCH3 ligados aos carbonos 1 e 4. O outro produto formado tem mais n moléculas do composto HOCH2CH2OH.\n\nO composto A, representado no esquema de reação, é o",
