  "enunciado": "O rótulo da embalagem de um cosmético informa que a dissolução de seu conteúdo, de acordo com suas especificações, rende 2,7 litros desse produto pronto para o uso. Uma pessoa será submetida a um tratamento estético em que deverá tomar um banho de imersão com esse produto numa banheira com capacidade de 0,3 metro cúbico. Para evitar o transbordamento, essa banheira será preenchida em 80 por cento de sua capacidade. Para esse banho, o número mínimo de embalagens desse cosmético é",
