  "enunciado": "Em uma fábrica de refrigerantes, é necessário que se faça periodicamente o controle no processo de engarrafamento para evitar que sejam envasadas garrafas fora da especificação do volume escrito no rótulo. Diariamente, durante 60 dias, foram anotadas as quantidades de garrafas fora dessas especificações. O resultado está apresentado no quadro.\n\nDescrição do quadro: O quadro mostra a quantidade de garrafas fora das especificações por dia e a quantidade de dias: 52 dias: 0 garrafa fora das especificações. 5 dias: 1 garrafa fora das especificações. 2 dias: 2 garrafas fora das especificações. 1 dia: 3 garrafas fora das especificações.\n\nA média diária de garrafas fora das especificações no período considerado é",
