  "enunciado": "Uma empresa de comunicação tem a tarefa de elaborar um material publicitário de um estaleiro para divulgar um novo navio, equipado com um guindaste de 15 metros de altura e uma esteira de 90 metros de comprimento. No desenho desse navio, a representação do guindaste deve ter sua altura entre 0,5 centímetro e 1 centímetro, enquanto a esteira deve apresentar comprimento superior a 4 centímetros. Todo o desenho deverá ser feito em uma escala 1 para X. Os valores possíveis para X são, apenas,",
