  "enunciado": "A Comissão Interna de Prevenção de Acidentes (CIPA) de uma empresa, observando os altos custos com os frequentes acidentes de trabalho ocorridos, fez, a pedido da diretoria, uma pesquisa do número de acidentes sofridos por funcionários. Essa pesquisa, realizada com uma amostra de 100 funcionários, norteará as ações da empresa na política de segurança no trabalho. Os resultados obtidos estão no quadro.\n\nDescrição do quadro: Quadro com as seguintes informações: Número de acidentes sofridos: 0; número de trabalhadores: 50. Número de acidentes sofridos: 1; número de trabalhadores: 17. Número de acidentes sofridos: 2; número de trabalhadores: 15. Número de acidentes sofridos: 3; número de trabalhadores: 10. Número de acidentes sofridos: 4; número de trabalhadores: 6. Número de acidentes sofridos: 5; número de trabalhadores: 2.\n\nA média do número de acidentes por funcionário na amostra que a CIPA apresentará à diretoria da empresa é",
