  "enunciado": "O carvão é um combustível que tem várias substâncias em sua composição. Em razão disso, quando é representada sua queima com o oxigênio, abre parêntese, massa molar 16 gramas por mol, fecha parêntese, simplifica-se elaborando apenas a combustão completa do carbono, abre parêntese, massa molar 12 gramas por mol, fecha parêntese. De acordo com o conteúdo médio de carbono fixo, o carvão é classificado em vários tipos, com destaque para o antracito, que apresenta, em média, 90 por cento de carbono. Esse elevado conteúdo favorece energeticamente a combustão, no entanto, libera maior quantidade de gás que provoca efeito estufa. Supondo a queima completa de 100 gramas de carvão antracito, a massa de gás liberada na atmosfera é, em grama, mais próxima de",
