  "enunciado": "A agricultura de frutas cítricas requer que o valor do pH do solo esteja na faixa ideal entre 5,8 e 6,0. Em uma fazenda, o valor do pH do solo é 4,6. O agricultor resolveu testar três produtos de correção de pH em diferentes áreas da fazenda. O primeiro produto possui íons sulfato e amônio, o segundo produto possui íons carbonato e cálcio e o terceiro produto possui íons sulfato e sódio. O íon que vai produzir o efeito desejado de correção no valor do pH é o",
  "alternativas": [
   "cálcio, porque sua hidrólise produz H de carga positiva, que aumenta a acidez.",
   "amônio, porque sua hidrólise produz H de carga positiva, que aumenta a acidez.",
   "sódio, porque sua hidrólise produz OH de carga negativa, que aumenta a alcalinidade.",
   "sulfato, porque sua hidrólise produz OH de carga negativa, que aumenta a alcalinidade.",
   "carbonato, porque sua hidrólise produz OH de carga negativa, que aumenta a alcalinidade."
  ],
  "resposta": 4,
