  "enunciado": "Os acidentes de trânsito são causados geralmente por excesso de velocidade. Em zonas urbanas no Brasil, o limite de velocidade normalmente adotado é de 60 quilômetros por hora. Uma alternativa para diminuir o número de acidentes seria reduzir esse limite de velocidade. Considere uma pista seca em bom estado, onde um carro é capaz de frear com uma desaceleração constante de 5 metros por segundo ao quadrado e que o limite de velocidade reduza de 60 quilômetros por hora para 50 quilômetros por hora.\n\nNessas condições, a distância necessária para a frenagem desde a velocidade limite até a parada completa do veículo será reduzida em um valor mais próximo de",
  "alternativas": [
   "1 metro.",
   "9 metros.",
   "15 metros.",
   "19 metros.",
   "38 metros."
  ],
