  "enunciado": "Na tentativa de explicar o processo evolutivo dos seres humanos, em 1981, Lynn Margulis propôs a teoria endossimbiótica, após ter observado que duas organelas celulares se assemelhavam a bactérias em tamanho, forma, genética e bioquímica. Acredita-se que tais organelas são descendentes de organismos procariontes que foram capturados por alguma célula, vivendo em simbiose. Tais organelas são as mitocôndrias e os cloroplastos, que podem se multiplicar dentro da célula. A multiplicação dessas organelas deve-se ao fato de apresentarem",
