  "enunciado": "Um caminhão de massa 5 toneladas, carregado com carga de 3 toneladas, tem eixos articulados que permitem fazer o uso de 4 a 12 pneus, abre parêntese, aos pares, fecha parêntese, simultaneamente. O número de pneus em contato com o solo é determinado a fim de que a pressão exercida por cada pneu contra o solo não supere o dobro da pressão atmosférica. A área de contato entre cada pneu e o asfalto equivale à área de um retângulo de lados 20 centímetros e 30 centímetros. Considere a aceleração da gravidade local igual a 10 metros por segundo ao quadrado e a pressão atmosférica, medida em Pascal, de 10 elevado a cinco. O menor número de pneus em contato com o solo que o caminhão deverá usar é",
