  "enunciado": "A fritura de alimentos é um processo térmico que ocorre a temperaturas altas, aproximadamente a 170 graus Celsius. Nessa condição, alimentos ricos em carboidratos e proteínas sofrem uma rápida desidratação em sua superfície, tornando-a crocante. Uma pessoa quer fritar todas as unidades de frango empanado congelado de uma caixa. Para tanto, ela adiciona todo o conteúdo de uma vez em uma panela com óleo vegetal a 170 graus Celsius, cujo volume é suficiente para cobrir todas as unidades. Mas, para sua frustração, ao final do processo elas se mostram encharcadas de óleo e sem crocância. As unidades ficaram fora da aparência desejada em razão da",
