  "enunciado": "O gerente de uma concessionária apresentou a seguinte tabela em uma reunião de dirigentes. Sabe-se que ao final da reunião, a fim de elaborar metas e planos para o próximo ano, o administrador avaliará as vendas, com base na mediana do número de automóveis vendidos no período de janeiro a dezembro.\n\nDescrição da tabela: Tabela que relaciona os meses do ano com o número de automóveis vendidos. Janeiro: 25 Fevereiro: 20 Março: 30 Abril: 35 Maio: 40 Junho: 50 Julho: 45 Agosto: 35 Setembro: 60 Outubro: 55 Novembro: 70 Dezembro: 65\n\nQual foi a mediana dos dados apresentados?",
