  "enunciado": "Um professor pediu aos seus alunos que esboçassem um gráfico representando a relação entre metro cúbico e litro de água, utilizando um software. Pediu ainda que representassem graficamente os pontos correspondentes às transformações de 0 metro cúbico, 2 metros cúbicos e 4 metros cúbicos em litro. O professor recebeu de cinco alunos os seguintes gráficos:\n\nDescrição dos gráficos: Gráficos nos quais o eixo x corresponde a metros cúbicos e o eixo y corresponde a litros, apresentam os seguintes dados: Gráfico 1: Segmento curvado ascendente com concavidade para baixo que se inicia em 0 metro cúbico e 0 litro, passando por 2 metros cúbicos e raiz cúbica de 2 litro, prosseguindo até 4 metros cúbicos e raiz cúbica de 4 litros;\n\nGráfico 2: Segmento curvado ascendente com concavidade para cima que se inicia em 0 metro cúbico e 0 litro, passando por 2 metros cúbicos e 400 litros, prosseguindo até 4 metros cúbicos e 1 600 litros;\n\nGráfico 3: Segmento de reta crescente que se inicia em 0 metro cúbico e 0 litro, passando por 2 metros cúbicos e 2 litros, prosseguindo até 4 metros cúbicos e 4 litros;\n\nGráfico 4: Segmento de reta crescente que se inicia em 0 metro cúbico e 0 litro, passando por 2 metros cúbicos e 200 litros, prosseguindo até 4 metros cúbicos e 400 litros;\n\nGráfico 5: Segmento de reta crescente que se inicia em 0 metro cúbico e 0 litro, passando por 2 metros cúbicos e 2 000 litros, prosseguindo até 4 metros cúbicos e 4 000 litros.\n\nO gráfico que melhor representa o esboço da transformação de metro cúbico para litro é o do aluno",
