  "enunciado": "O nanofio é um feixe de metais semicondutores usualmente utilizado na fabricação de fibra óptica. A imagem ilustra, sem escala, as representações das medidas dos diâmetros de um nanofio e de um fio de cabelo, possibilitando comparar suas espessuras e constatar o avanço das novas tecnologias.\n\nDescrição da imagem: Desenho de um nanofio, cujo diâmetro, em metro, é 10 elevado a menos 9, e de um fio de cabelo, cujo diâmetro, em metro, é 6 vezes 10 elevado a menos 5.\n\nO número que expressa a razão existente entre o comprimento do diâmetro de um fio de cabelo e o de um nanofio é",
