  "enunciado": "Em um município existem cinco clubes esportivos. Cada um possui uma bandeira, e a proporcionalidade entre largura e comprimento dessas bandeiras são distintas. O quadro mostra a proporcionalidade oficial entre largura e comprimento das bandeiras desses cinco clubes.\n\nDescrição do quadro: O quadro apresenta o clube e a proporcionalidade entre largura e comprimento da sua respectiva bandeira. No clube 1 a proporcionalidade é de 7 para 10. No clube 2 a proporcionalidade é de 10 para 19. No clube 3 a proporcionalidade é de 2 para 3. No clube 4 a proporcionalidade é de 18 para 28. No clube 5 a proporcionalidade é de 2 para 4.\n\nPretende-se hastear as bandeiras desses clubes durante a abertura de um evento esportivo do munícipio. A direção do evento decidiu, então, confeccionar as cinco bandeiras, de forma a obter a mesma largura para todas, obedecendo-se à proporcionalidade oficial. A bandeira que terá o menor comprimento será a do clube",
