  "enunciado": "Uma dona de casa vai ao supermercado para comprar dois fardos de refrigerantes, contendo cada um deles seis unidades de 0,6 litro. Lá chegando, verificou não existirem fardos nem no formato e nem na capacidade desejados. Decidiu, então, comprar os refrigerantes em unidades avulsas, de mesma capacidade, de forma a obter, no mínimo, a mesma quantidade de líquido desejada inicialmente, gastando o mínimo de dinheiro. As opções de embalagens e respectivos preços existentes no supermercado são dados no quadro.\n\nDescrição do quadro: O quadro apresenta cinco tipos de embalagens desse refrigerante, por capacidade, com seus respectivos custos. Embalagem de 3 litros: custo de 4,39 reais; Embalagem de 2,5 litros: custo de 3,69 reais; Embalagem de 2 litros: custo de 2,89 reais; Embalagem de 1,5 litro: custo de 2,19 reais; Embalagem de 1 litro: custo de 1,99 real.\n\nQual é a opção de embalagem, em litro, que proporcionará maior economia para essa dona de casa?",
