  "enunciado": "Um professor realizou um experimento em que uma lanterna e um despertador foram acionados no interior de um recipiente de vidro, no qual foi feito vácuo. Os alunos perceberam a luz, mas não detectaram o som se propagando externamente. O resultado observado confirma que:",
