  "enunciado": "Muitos pais brasileiros jovens nunca viram pessoas com sarampo e, assim, não se preocuparam com a imunização de seus filhos. Em consequência, foi observado um aumento do número de casos de sarampo em algumas cidades brasileiras nos últimos anos.\n\nEsse aumento do número de casos dessa doença no Brasil deve ter sido consequência direta da",
