  "enunciado": "A aceleração da gravidade na Lua é aproximadamente seis vezes menor do que na Terra. Quando o homem foi à Lua, mediu a massa e o peso de um objeto. A massa e o peso desse objeto já haviam sido medidos na Terra. Comparando as medidas realizadas na Lua com as realizadas na Terra, observa-se que:",
  "alternativas": [
   "A massa e o peso se alteram.",
   "A massa e o peso permanecem os mesmos.",
   "A massa se altera, mas o peso permanece o mesmo.",
   "A massa permanece a mesma, mas o peso se altera."
  ],
  "resposta": 3,
