  "enunciado": "Um programa de televisão oferece aos participantes a oportunidade de ganharem uma TV sorteando uma bola dentre as 100 bolas de uma urna, sendo 95 brancas e 5 douradas. Ganha o prêmio o participante que retirar uma bola dourada. A produção desse programa pretende reduzir a probabilidade de a TV ser sorteada e, para isso, decide acrescentar na urna novas bolas brancas, mantendo as 5 bolas douradas. Qual quantidade de bolas brancas deve ser acrescentada à urna para que a probabilidade de um participante ganhar a TV seja de 4%?",
