  "enunciado": "O vazamento do gás liquefeito do petróleo (GLP), usado em botijões de gás nas cozinhas, pode provocar incêndios. A manutenção das mangueiras do botijão deve ser frequente, verificando-se se está vedando a saída do gás. Procedimentos como usar água com sabão na junção da mangueira com a válvula do botijão ajudam a verificar vazamentos. O que acontece ao se utilizar esse procedimento?",
  "alternativas": [
   "Interrupção do vazamento do gás.",
   "Aparecimento de bolhas indicando a saída do gás.",
   "Favorecimento do encaixe da válvula na mangueira.",
   "Limpeza da parte da válvula para evitar que o gás escape."
  ],
