  "enunciado": "Um mesmo televisor é vendido em quatro lojas diferentes (I, II, III e IV) com as seguintes opções de pagamento:\n• loja I: entrada de R$ 0,00 e o valor do televisor pago em 10 parcelas iguais de R$ 46,00;\n• loja II: entrada de R$ 100,00 e o valor do televisor pago em 12 parcelas iguais de R$ 40,00;\n• loja III: entrada de R$ 150,00 e o valor do televisor pago em 6 parcelas iguais de R$ 50,00;\n• loja IV: entrada de R$ 200,00 e o valor do televisor pago em 4 parcelas iguais de R$ 80,00. A loja em que o valor total pago pelo televisor será o menor é a de número",
