  "enunciado": "Um senhor de 45 anos de idade trabalha 8 horas por dia em um escritório de contabilidade. Por ocasião de seus afazeres profissionais, ele fica o dia inteiro sentado em frente a um computador. Nos finais de semana, costuma sentar-se para assistir a programas de televisão e se distrair durante horas seguidas. Nos últimos meses, esse senhor tem se queixado muito de dores na coluna. Para a melhoria de sua qualidade de vida, seria adequado recomendar-lhe o(a)",
