  "enunciado": "Motoristas que dirigem constantemente em estradas sem pavimento, com subidas e descidas, e transportam cargas reconhecem os benefícios de automóveis que possuem tração traseira. Isso se explica pelo deslocamento do centro de massa do veículo para trás quando este está carregado. Considere um veículo em subida que possui tração traseira e esteja carregado. Os sentidos da força de atrito, em relação à direção do movimento, que atua nas rodas dianteiras e traseiras são, respectivamente,",
