  "enunciado": "Dificilmente se utilizam metais puros para a fabricação dos objetos metálicos. Um exemplo interessante são as joias em ouro, cuja tonalidade e cor variam conforme as diferentes composições. O ouro amarelo, por exemplo, contém 75% de ouro, 13% de cobre e 12% de prata. Já o ouro branco contém 70% de ouro e 25% de paládio, ou 75% de ouro, 12,5% de prata e 12,5% de paládio. Nessas joias, as misturas sólidas formadas por átomos de metais ou outros elementos são denominadas",
