  "enunciado": "A agricultura é a atividade humana da qual provém a maior fonte de alimento do mundo, mas as técnicas utilizadas por alguns agricultores contribuem para a degradação ambiental. Uma técnica que pode ser considerada ambientalmente adequada é o(a)",
