  "enunciado": "Uma das maneiras de se medir o desempenho de um automóvel é calcular a razão entre a distância percorrida (em km) e o volume de combustível (em litro) gasto nesse percurso. As informações a seguir foram obtidas a respeito de quatro automóveis movidos a gasolina:\n• automóvel I: percorre 286 km com 13 L;\n• automóvel II: percorre 288 km com 16 L;\n• automóvel III: percorre 255 km com 15 L;\n• automóvel IV: percorre 250 km com 12 L. A partir dessas informações, o automóvel que apresentou o melhor desempenho, ao utilizar gasolina, foi o",
