  "enunciado": "Um produto é vendido por R$ 120,00. Para aumentar as vendas, o dono da loja decide dar um desconto no preço desse produto. Ele sabe que o desconto deve ser, no máximo, igual a 30% para que não tenha prejuízo. O valor mínimo pelo qual o produto com desconto deve ser vendido é",
