  "enunciado": "Em um município, foi feita uma campanha de arrecadação de mantimentos em prol dos moradores que sofreram perdas devido a uma enchente. Um dos produtos arrecadados foi arroz. Um grupo decidiu preparar uma cesta básica para cada família afetada pelas cheias. Ao montar as cestas, perceberam que, colocando 2 quilogramas de arroz em cada uma, sobrariam 76 quilogramas desse produto, e colocando 4 quilogramas, faltariam 14 quilogramas de arroz para completar as cestas básicas. Quantos quilogramas de arroz foram arrecadados nessa campanha?",
