  "enunciado": "Agrotóxicos ou pesticidas são nomes usados de forma popular para produtos que atacam pragas, principalmente as das lavouras, como insetos. Atualmente, discute-se muito sobre a escolha entre consumir alimentos tratados e contaminados com pesticidas fabricados artificialmente ou consumir produtos orgânicos, livres de pesticidas, mas ainda mais caros do que os outros. Embora esses produtos artificiais possam causar transtornos para a saúde humana, sua utilização na lavoura ainda é considerada necessária porque eles",
  "alternativas": [
   "estimulam o crescimento das plantas, aumentando seu tamanho.",
   "eliminam as pragas que atacam as plantas, melhorando a produtividade agrícola.",
   "melhoram a absorção de nutrientes pelos vegetais, deixando-os mais saborosos.",
   "alteram a aparência original dos vegetais, tornando-os mais nutritivos."
  ],
