  "enunciado": "A energia total média necessária ao nosso corpo para as atividades que desenvolvemos no nosso dia a dia é de 8 000 quilojoules. Podemos comparar essa quantidade com a energia necessária para manter um número de lâmpadas de 40 watts acesas durante um tempo de 400 segundos. Sabe-se que: 1 watt = 1 joule por segundo 1 quilojoule = 1 000 joules Nessa comparação, qual é o maior número de lâmpadas que podem ser mantidas acesas durante esse tempo?",
