  "enunciado": "Para fazer uma receita, uma pessoa precisa comprar os seguintes produtos: óleo, vinagre e molho de tomate. Antes de sair para comprar, ela fez uma pesquisa em folhetos de quatro supermercados diferentes e encontrou os seguintes valores para as mesmas marcas dos produtos:\n• Supermercado I: óleo 1 litro – R$ 2,45; vinagre 750 mL – R$ 1,50; molho de tomate 340 g – R$ 2,90.\n• Supermercado II: óleo 1 litro – R$ 3,15; vinagre 750 mL – R$ 1,30; molho de tomate 340 g – R$ 2,50.\n• Supermercado III: óleo 1 litro – R$ 3,40; vinagre 750 mL – R$ 1,25; molho de tomate 340 g – R$ 2,50.\n• Supermercado IV: óleo 1 litro – R$ 2,70; vinagre 750 mL – R$ 1,40; molho de tomate 340 g – R$ 2,50. Essa pessoa pretende comprar os três produtos no mesmo supermercado, de modo a obter o menor valor total a pagar. Em qual desses supermercados deve ser realizada a compra?",
