  "enunciado": "Um entregador utiliza em seu trabalho um caminhão com um tanque de combustível com capacidade para 100 litros e que percorre, em média, 7 km com 1 litro de óleo diesel. Em seu trajeto diário de entregas, ele percorre 84 km. Estando o tanque de combustível inicialmente cheio, a quantidade q de litros de óleo diesel que restam no tanque de combustível do caminhão depende da quantidade d de dias trabalhados. A representação algébrica que descreve a quantidade q de óleo diesel restante no tanque, em função da quantidade d de dias trabalhados, é",
