  "enunciado": "Um cliente recebeu sua fatura mensal do cartão de crédito no valor de R$ 2 500,00 mas não podia fazer o pagamento integral da fatura. Para quitação do débito de forma parcelada, a administradora do cartão de crédito ofereceu os seguintes planos de pagamento:\n• Plano 1: entrada de R$ 900,00 mais uma parcela de R$ 1 800,00.\n• Plano 2: entrada de R$ 400,00 mais saldo devedor de R$ 2 100,00 acrescido de juros de 10%.\n• Plano 3: entrada de R$ 1 500,00 mais saldo devedor de R$ 1 000,00 acrescido de juros de 15%.\n• Plano 4: entrada de R$ 500,00 mais saldo devedor de R$ 2 000,00 acrescido de juros de 9%. A qual desses planos o cliente deve aderir para ter o menor gasto total com o pagamento dessa fatura?",
  "alternativas": [
   "1",
   "2",
   "3",
   "4"
  ],
