  "enunciado": "Um engenheiro está criando um programa para ser utilizado em um jogo de computador. Para testar esse programa, ele simula uma caixa contendo inicialmente duas bolinhas brancas. Um segundo após o início da simulação, uma das bolinhas brancas se torna azul e a outra se torna vermelha. Em cada segundo subsequente, a quantidade de bolinhas azuis é duplicada, enquanto que a quantidade de bolinhas vermelhas é triplicada. A simulação deverá ser interrompida no exato segundo em que a quantidade total de bolinhas na caixa superar 96. Depois de quanto tempo, em segundo, após ter sido iniciada, a simulação deverá ser interrompida?",
