  "enunciado": "Até o princípio do século XX, provar a paternidade era um drama. A justiça baseava-se em evidências materiais, como cartas, fotos e depoimentos de testemunhas, mas, mesmo assim, ainda poderiam pairar dúvidas sobre a questão. Atualmente, programas sociais têm assegurado a crianças, jovens e adultos o reconhecimento e a inclusão do nome de seus pais em suas certidões de nascimento. Após a década de 1990, esse tipo de comprovação ficou segura e está cada vez mais acessível, graças ao(à)",
