  "enunciado": "O uso de pílulas anticoncepcionais como método contraceptivo, apesar de ser um dos mais eficientes no controle de natalidade, não previne contra doenças sexualmente transmissíveis (DSTs). A ineficácia desse contraceptivo com relação às DSTs deve-se ao fato de esse método",
