  "enunciado": "O suco gástrico, entre outras substâncias, contém grande quantidade de ácido clorídrico (HCl). A ingestão de alguns alimentos pode causar um mal-estar, conhecido como azia, quando a concentração desse ácido é muito alta. Para neutralizar o efeito dessa substância no organismo, deve-se ingerir",
